/**
 * Catalog of the six decision types (Stage 05): units, ranges, defaults with their
 * sources, and the mechanism of each decision.
 *
 * The JSON is generated by `python -m multiverse_contracts.catalog` from the Python
 * contracts, which also validate it, so the cast below is safe. It is the payload of
 * the future `GET /api/v1/interventions/types`.
 */
import type {
  FixedValue,
  InterventionCatalog,
  ScenarioDraft,
  TriangularRange,
  UniformRange,
} from "./generated/contracts";
import data from "../../catalog/interventions.json";

export type Distribution = FixedValue | UniformRange | TriangularRange;
export type Decision = ScenarioDraft["decision"];
export type DecisionType = Decision["type"];

// JSON imports widen literal types; the Python contracts validate the file in CI.
export const INTERVENTION_CATALOG: InterventionCatalog = data as unknown as InterventionCatalog;
